#!/usr/bin/env python3
"""Build an investigative review page for HGAB rows without Transparency links."""
import json, re, unicodedata
from pathlib import Path
from uniform_report_menu import apply_page as apply_report_chrome
ROOT=Path(__file__).resolve().parent
OUT=ROOT/'analysis_output'; STATIC=ROOT.parent/'open-data-visualization/static/nep-preview'

def read(name): return json.loads((OUT/name).read_text())
def key(s): return ' '.join(unicodedata.normalize('NFKC',str(s or '')).split())
def main():
    stage=read('dpwh_hgab_2nd_vs_3rd.json')['rows']
    mapping=read('hb_nep_comparison_3rd_mapping.json')
    indepth=read('dpwh-in-depth-data.json')
    coverage=read('dpwh_transparency_document_coverage.json')
    review=read('line_item_review_queue.json')
    repeats=read('within_stage_repeats.json')
    historical=read('repeat-hgab-historical-gaa.json')
    crosswalk=read('deo_leg_boundary_crosswalk.json')
    deo_legs={}
    for cp in crosswalk.get('pairs',[]):
        deo_legs.setdefault(key(cp.get('deo')).casefold(),[]).append({k:cp.get(k) for k in ('leg','legProvince','status','deoAreaFraction','legAreaFraction')})
    pair_by={p.get('hgabId'):p for p in mapping.get('pairs',[]) if p.get('hgabId')}
    unpaired={p.get('id') for p in mapping.get('hgabWithoutSelectedCounterpart',[]) if p.get('allocationKind')=='project'}
    by_code={p.get('code'):p for p in indepth.get('projects',[]) if p.get('code')}
    source_rows={r.get('sourceId'):r for r in coverage.get('rows',[]) if r.get('sourceId')}
    titles=coverage.get('titles',{})
    queue={r['hgabId']:r for r in review.get('rankedOccurrences',[]) if r.get('hgabId')}
    hist={}
    for r in historical.get('rows',[]): hist.setdefault(r['hgabId'],[]).append(r)
    same_stage={}
    for pair in repeats.get('pairs',[]):
        for side in ('left','right'):
            item=pair.get(side) or {}; hid=item.get('hgabId') or item.get('id')
            if hid: same_stage.setdefault(hid,[]).append(pair)
    allrows=[]
    for entry in stage:
        row=entry.get('third')
        if not row or row.get('allocationKind')!='project': continue
        title=titles.get(key(row.get('projectName')))
        status=title.get('status','unmapped') if title else 'unmapped'
        direct=None
        if title and title.get('code') and status not in {'not_found','no_verified_match','candidate_match','ambiguous_match','outside_snapshot_scope'}:
            direct=by_code.get(title['code'])
        pair=pair_by.get(row.get('id'))
        nep=source_rows.get((pair.get('nep') or {}).get('id')) if pair else None
        paired=by_code.get(nep.get('code')) if nep and nep.get('code') else None
        urls={str(d.get('url')) for p in (direct,paired) if p for d in p.get('documentLinks',[]) if d.get('url')}
        if urls: continue
        q=queue.get(row.get('id'),{})
        project={
            'id':row.get('id'),'title':row.get('projectName'),'amountPesos':row.get('amountPesos') or 0,
            'program':row.get('pap3') or row.get('pap2') or row.get('pap1') or '',
            'office':row.get('office') or '', 'region':row.get('region') or '',
            'sourceVolume':row.get('sourceVolume') or '', 'sourcePage':row.get('sourcePage'),
            'documentStatus':status,'nepPairStatus':pair.get('kind') if pair else 'no selected NEP counterpart',
            'nepTitle':(pair or {}).get('nep',{}).get('projectName','') if pair else '',
            'nepHasDocumentLinks':bool(paired and paired.get('documentLinks')),
            'flags':[{'id':f.get('id'),'label':f.get('label'),'evidence':f.get('evidence'),'summaryFinding':f.get('summaryFinding')} for f in q.get('flags',[])],
            'flagCount':q.get('flagCount',0),'evidenceCautions':q.get('evidenceCautions',[]),
            'districts':q.get('districts',[]),
            'deoLegCrosswalk':deo_legs.get(key(row.get('office')).casefold(),[]),
            'historicalMatches':[{'gaaYear':m.get('gaaYear'),'gaaTitle':m.get('gaaTitle'),'gaaAmountPesos':m.get('gaaAmountPesos'),'chainageStatus':m.get('chainageStatus')} for m in hist.get(row.get('id'),[])],
            'withinStageRepeatPairs':[{'kind':p.get('kind'),'titleSimilarity':p.get('titleSimilarity'),'left':{'projectName':(p.get('left') or {}).get('projectName'),'title':(p.get('left') or {}).get('title')},'right':{'projectName':(p.get('right') or {}).get('projectName'),'title':(p.get('right') or {}).get('title')}} for p in same_stage.get(row.get('id'),[])]
        }
        allrows.append(project)
    allrows.sort(key=lambda r:(-r['flagCount'],-r['amountPesos'],r['title'].casefold()))
    expected=indepth['hgabCoverage']['missingListedDocumentsRows']
    if len(allrows)!=expected: raise SystemExit(f'No-doc reconciliation mismatch: built {len(allrows)}, expected {expected}')
    # The local GAB comparison is only aggregate evidence; do not invent project-level exclusions.
    data={'summary':{'noDocumentProjects':len(allrows),'amountPesos':sum(r['amountPesos'] for r in allrows),
        'withReviewFlags':sum(bool(r['flags']) for r in allrows),'withNoSelectedNep':sum(r['nepPairStatus']=='no selected NEP counterpart' for r in allrows),
        'withinStageRepeatCandidates':sum(bool(r['withinStageRepeatPairs']) for r in allrows),
        'gabRemovedItemsReported':295,'gabRemovedPesosReported':8836000000},
        'provenance':{'hgab':'FY2027 HGAB 3rd-reading DPWH project ledger','documents':'DPWH Transparency metadata snapshot; direct HGAB title links plus selected NEP counterpart links','documentSnapshot':indepth['hgabCoverage'].get('snapshotRetrievedAtUtc'),
        'deoLegCrosswalk':'analysis_output/deo_leg_boundary_crosswalk.json; spatial intersection evidence, dates unverified',
        'gab':'User-provided aggregate (295 items / ₱8.836B); no item-level Senate/GAB rows are present in the local project inputs, so no individual HGAB records are marked removed.'},'projects':allrows}
    payload=json.dumps(data,ensure_ascii=False,separators=(',',':'))
    html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HGAB projects without document links · BetterGov</title><style>
:root{--navy:#00246a;--blue:#0648a8;--gold:#fcd116;--ink:#18232d;--muted:#586877;--line:#d9e1e8;--paper:#f3f6f8;--red:#a43c25}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 system-ui,sans-serif}header{background:var(--navy);color:white;padding:28px clamp(16px,4vw,54px);border-bottom:6px solid var(--gold)}h1{margin:4px 0;font-size:clamp(28px,4vw,44px)}header p{max-width:950px;color:#edf3ff}main{padding:20px clamp(12px,3vw,40px);max-width:1800px;margin:auto}.warning,.card,.stat{background:#fff;border:1px solid var(--line);border-radius:12px;padding:16px;margin:14px 0}.warning{border-left:5px solid var(--gold)}.warning.red{border-left-color:var(--red);background:#fff8f5}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stat{margin:0}.gab-title{display:flex;justify-content:space-between;align-items:center;gap:16px}.gab-title strong{font-size:clamp(30px,5vw,48px);color:var(--navy);white-space:normal;text-align:right;max-width:55%}.gab-title strong span{display:block}.gab-count-line{display:grid;grid-template-columns:1fr auto;align-items:baseline;gap:12px;margin-top:3px;font-size:13px;color:var(--muted);font-variant-numeric:tabular-nums}.gab-count-line strong{font-size:inherit;white-space:nowrap;color:var(--ink);text-align:right}.gab-bars{display:grid;gap:18px;margin-top:18px}.gab-bar-row{display:grid;grid-template-columns:minmax(180px,1fr) 2fr;gap:16px;align-items:center}.gab-bar-label strong,.gab-bar-label span{display:block}.gab-bar-label span{font-size:13px;color:var(--muted)}.gab-stack{display:flex;height:26px;overflow:hidden;border-radius:7px;background:#e7edf2}.gab-removed{background:#2e8b57}.gab-remain{background:var(--red)}.gab-legend{display:flex;gap:16px;flex-wrap:wrap;font-size:12px;color:var(--muted);margin-top:12px}.gab-legend span:before{content:"";display:inline-block;width:10px;height:10px;border-radius:2px;background:#2e8b57;margin-right:6px}.gab-legend span+span:before{background:var(--red)}.stat strong{display:block;font-size:26px;color:var(--navy)}.muted,.small{color:var(--muted)}.small{font-size:13px}.filters{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.filters input,.filters select{padding:9px;border:1px solid #aab8c5;border-radius:7px;background:white;font:inherit}.filters input{flex:1;min-width:230px}.tablewrap{overflow:auto;max-height:72vh;border:1px solid var(--line);border-radius:8px}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;vertical-align:top;padding:9px;border-bottom:1px solid var(--line);overflow-wrap:anywhere}th{position:sticky;top:0;background:#edf2f7;z-index:1}td.num{text-align:right;white-space:nowrap}.tag{display:inline-block;background:#eef3fa;padding:2px 7px;border-radius:20px;margin:2px;font-size:12px}.redtag{background:#ffebe6;color:#8c2917}.pagination{display:flex;justify-content:flex-end;align-items:center;gap:10px;padding:10px}.pagination button{padding:7px 11px;background:white;border:1px solid #aab8c5;border-radius:6px}details{margin:8px 0}h2{color:var(--navy);margin:0 0 8px}@media(max-width:750px){.stats{grid-template-columns:1fr 1fr}.gab-bar-row{grid-template-columns:minmax(0,1fr);gap:8px}.gab-title{align-items:flex-start}.gab-title strong{font-size:clamp(22px,5vw,32px);max-width:58%}}
</style></head><body><header><div>FY2027 · HOUSE GAB (HGAB) · DPWH</div><h1>Projects with no document links</h1><p>Review HGAB projects with no DPWH Transparency links via title or selected NEP counterpart. Examine flags, repeats, cost signals and district context.</p></header><main><div class="warning"><strong>Document gap, not proof of nonexistence.</strong> “No documents” means no link was found in the loaded Transparency snapshot through either route. Documents may exist elsewhere, be listed under another title, or be missing from this snapshot.</div><div class="warning red"><strong>Senate/GAB scope note.</strong> The stated commitment was to remove all HGAB projects without documents. The reported Senate/GAB change is 295 items totaling ₱8.836B. Against this 6,378-project no-link cohort, that leaves 6,083 projects and about ₱175.091B (95.4% of rows and 95.2% of allocation). The local inputs lack item-level GAB rows, so individual removals remain unmatched; the aggregate comparison follows the reported claim that these items came from this cohort.</div><div id="stats" class="stats"></div><section class="card"><div class="gab-title"><div><p class="small" style="text-transform:uppercase;letter-spacing:.08em">Senate/GAB reported removals</p><h2>The stated commitment was to remove all undocumented projects. Nearly all remain.</h2></div><strong id="gab-highlight"></strong></div><div id="gab-bars" class="gab-bars"></div><div class="gab-legend"><span>Removed in Senate/GAB</span><span>Still in HGAB list without found document links</span></div><p class="small muted">The remaining shares are the focus: 6,083 of 6,378 projects (95.4%) and about ₱175.091B of ₱183.927B (95.2%) remain after the reported removals. If the commitment was to remove every project without documents, the reported reduction falls far short. This is an aggregate comparison; item-level Senate/GAB identities are still unmatched.</p></section><section class="card"><h2>Investigation queue</h2><p class="muted">Sort starts with the number of independent review signals, then allocation. Signals are screening leads, not findings. Select a row for the source context and individual methods.</p><div class="filters"><input id="q" type="search" placeholder="Search title, office, region, program, district"><select id="flag"><option value="">All review-flag counts</option></select><select id="program"><option value="">All programs</option></select><select id="region"><option value="">All regions</option></select><select id="crosswalk"><option value="">All DEO–LEG coverage</option><option value="mapped">Has spatial crosswalk row</option><option value="unmapped">No spatial crosswalk row</option></select><select id="sort"><option value="flags">Most flags</option><option value="amount">Largest allocation</option><option value="title">Project title</option></select><button id="export" type="button">Export filtered CSV</button></div><div class="tablewrap"><table><thead><tr><th>Project / source</th><th>Office · region</th><th>Program</th><th>Allocation</th><th>Flags</th><th>Repeat evidence</th><th>NEP / document route</th><th>DEO → LEG crosswalk evidence</th></tr></thead><tbody id="rows"></tbody></table></div><div class="pagination"><button id="prev">Previous</button><span id="page"></span><button id="next">Next</button></div></section><section class="card"><h2>Methods and limits</h2><ul><li><b>Document screen:</b> a link counts when present directly on the HGAB title match or on the selected NEP counterpart. Pairing does not prove the NEP documents have identical scope to the HGAB line.</li><li><b>Red flags and cost clustering:</b> exact HGAB ID join to the existing line-item review queue. This carries its repeated-allocation clusters, high unit-cost signals, historical comparisons and related cautions. Candidate flags need source and scope review.</li><li><b>Repeated projects:</b> within-stage repeat pairs and prior-GAA title candidates are attached where exact HGAB IDs match. Similar titles or costs alone do not prove duplicate scope.</li><li><b>DEO clustering:</b> the review queue's district/representative associations are shown as leads. A DEO may serve multiple legislative districts; the office total is not split or attributed to an individual legislator.</li><li><b>LEG crosswalk:</b> the DEO is joined to spatially intersecting legislative districts using the existing boundary crosswalk. Overlap does not assign a project to a district, member, sponsor or controller; boundary dates are unverified and multi-district DEOs remain shared.</li><li><b>Senate/GAB removal:</b> only the aggregate 295 / ₱8.836B figure is available in the local inputs. Project-level inclusion remains unresolved until the Senate/GAB rows are matched.</li></ul><p class="small">Sources: HGAB 3rd-reading DPWH ledger; DPWH Transparency project/document snapshot; selected NEP–HGAB mapping; line-item review queue; within-stage repeat screen; historical GAA repeat screen; DEO–LEG boundary crosswalk. Snapshot: __SNAPSHOT__.</p></section><div id="detail" class="card" hidden></div></main><script>
fetch('undocumented-hgab-data.json').then(r=>{if(!r.ok)throw new Error('Could not load the project data');return r.json()}).then(D=>{const S=D.summary,fmt=n=>Number(n||0).toLocaleString('en-PH'),peso=n=>'₱'+fmt(Math.round(Number(n||0))),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));document.getElementById('stats').innerHTML=[[fmt(S.noDocumentProjects),'HGAB projects without found document links'],[peso(S.amountPesos),'combined listed allocation'],[fmt(S.withNoSelectedNep),'without a selected NEP counterpart'],[fmt(S.withinStageRepeatCandidates),'with a within-stage repeat candidate']].map(x=>`<div class="stat"><strong>${esc(x[0])}</strong><span>${esc(x[1])}</span></div>`).join('');const projectRemovedPct=100*S.gabRemovedItemsReported/S.noDocumentProjects,costRemovedPct=100*S.gabRemovedPesosReported/S.amountPesos,projectRemainPct=100-projectRemovedPct,costRemainPct=100-costRemovedPct;document.getElementById('gab-highlight').innerHTML=`<span>${projectRemainPct.toFixed(1)}% of projects remain</span><span>${costRemainPct.toFixed(1)}% of allocation remains</span>`;document.getElementById('gab-bars').innerHTML=[[`Projects`,fmt(S.noDocumentProjects-S.gabRemovedItemsReported),fmt(S.gabRemovedItemsReported),projectRemovedPct],[`Allocation`,peso(S.amountPesos-S.gabRemovedPesosReported),peso(S.gabRemovedPesosReported),costRemovedPct]].map(([label,remain,removed,removedPct])=>`<div class="gab-bar-row"><div class="gab-bar-label"><strong>${esc(label)}</strong><div class="gab-count-line"><span>remain</span><strong>${esc(remain)}</strong></div><div class="gab-count-line"><span>removed</span><strong>${esc(removed)}</strong></div></div><div class="gab-stack" role="img" aria-label="${(100-removedPct).toFixed(1)} percent remain; ${removedPct.toFixed(1)} percent removed"><span class="gab-remain" style="width:${100-removedPct}%"></span><span class="gab-removed" style="width:${removedPct}%"></span></div></div>`).join('');
const q=document.getElementById('q'),flag=document.getElementById('flag'),program=document.getElementById('program'),region=document.getElementById('region'),crosswalk=document.getElementById('crosswalk'),sort=document.getElementById('sort');[...new Set(D.projects.map(x=>x.flagCount))].sort((a,b)=>a-b).forEach(x=>flag.insertAdjacentHTML('beforeend',`<option value="${x}">${x} flags</option>`));[...new Set(D.projects.map(x=>x.program).filter(Boolean))].sort().forEach(x=>program.insertAdjacentHTML('beforeend',`<option>${esc(x)}</option>`));[...new Set(D.projects.map(x=>x.region).filter(Boolean))].sort().forEach(x=>region.insertAdjacentHTML('beforeend',`<option>${esc(x)}</option>`));let pg=0,selected=null;function filtered(){let a=D.projects.filter(x=>(!q.value||[x.title,x.office,x.region,x.program,(x.districts||[]).join(' ')].join(' ').toLowerCase().includes(q.value.toLowerCase()))&&(!flag.value||String(x.flagCount)===flag.value)&&(!program.value||x.program===program.value)&&(!region.value||x.region===region.value)&&(!crosswalk.value||(crosswalk.value==='mapped'?x.deoLegCrosswalk.length>0:x.deoLegCrosswalk.length===0)));if(sort.value==='amount')a.sort((x,y)=>y.amountPesos-x.amountPesos);else if(sort.value==='title')a.sort((x,y)=>x.title.localeCompare(y.title));else a.sort((x,y)=>y.flagCount-x.flagCount||y.amountPesos-x.amountPesos);return a}function exportCsv(){const rows=filtered(),cols=['HGAB ID','Project','Allocation pesos','Program','DEO','Region','Source volume','Source page','Document lookup status','NEP pairing','NEP counterpart','Review flags','Flag evidence','Historical GAA candidates','Within-stage repeat candidates','LEG crosswalk evidence'];const cell=v=>'\"'+String(v??'').replaceAll('\"','\"\"')+'\"';const lines=[cols,...rows.map(x=>[x.id,x.title,x.amountPesos,x.program,x.office,x.region,x.sourceVolume,x.sourcePage,x.documentStatus,x.nepPairStatus,x.nepTitle,x.flags.map(f=>f.label).join('; '),x.flags.map(f=>f.evidence).join('; '),x.historicalMatches.map(m=>`FY${m.gaaYear}: ${m.gaaTitle} (\u20b1${m.gaaAmountPesos})`).join('; '),x.withinStageRepeatPairs.map(p=>`${p.kind}: ${(p.left?.projectName||p.left?.title||'')} / ${(p.right?.projectName||p.right?.title||'')}`).join('; '),x.deoLegCrosswalk.map(c=>`${c.leg} [${c.status}; DEO overlap ${fmt(Number(c.deoAreaFraction||0)*100)}%]`).join('; ')])].map(r=>r.map(cell).join(',')).join('\\r\\n');const blob=new Blob(['\ufeff',lines],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='undocumented-hgab-filtered.csv';a.click();URL.revokeObjectURL(url)}document.getElementById('export').onclick=exportCsv;function draw(){let a=filtered(),size=50,pages=Math.max(1,Math.ceil(a.length/size));pg=Math.min(pg,pages-1);document.getElementById('rows').innerHTML=a.slice(pg*size,(pg+1)*size).map((x,i)=>`<tr data-id="${esc(x.id)}"><td><button class="open">${esc(x.title)}</button><div class="small">${esc(x.id)} · ${esc(x.sourceVolume)} p.${esc(x.sourcePage)}</div></td><td>${esc(x.office)}<br>${esc(x.region)}</td><td>${esc(x.program)}</td><td class="num">${peso(x.amountPesos)}</td><td>${x.flags.map(f=>`<span class="tag redtag" title="${esc(f.evidence)}">${esc(f.label)}</span>`).join('')||'No queue flag'}</td><td>${x.historicalMatches.length?`${x.historicalMatches.length} historical GAA candidate(s)`:''}${x.withinStageRepeatPairs.length?`${x.historicalMatches.length?'<br>':''}${x.withinStageRepeatPairs.length} within-stage pair(s)`:''}${!x.historicalMatches.length&&!x.withinStageRepeatPairs.length?'No repeat candidate':''}</td><td>${esc(x.nepPairStatus)}${x.nepHasDocumentLinks?'<br>Selected NEP counterpart has links':''}</td><td>${x.deoLegCrosswalk.length?x.deoLegCrosswalk.slice(0,5).map(c=>`${esc(c.leg)} (${esc(c.status)})`).join('<br>')+(x.deoLegCrosswalk.length>5?`<br>+${x.deoLegCrosswalk.length-5} more`: ''):'No spatial DEO–LEG row'}<div class="small">Queue district lead: ${esc(x.districts.join('; ')||'none')}</div></td></tr>`).join('');document.getElementById('page').textContent=`${a.length?pg*size+1:0}–${Math.min((pg+1)*size,a.length)} of ${fmt(a.length)}`;document.getElementById('prev').disabled=pg===0;document.getElementById('next').disabled=pg>=pages-1;document.querySelectorAll('.open').forEach(b=>b.onclick=()=>{selected=b.closest('tr').dataset.id;detail()})}function detail(){const x=D.projects.find(p=>p.id===selected),d=document.getElementById('detail');if(!x)return;d.hidden=false;d.innerHTML=`<h2>${esc(x.title)}</h2><p>${esc(x.office)} · ${esc(x.region)} · ${esc(x.program)} · ${peso(x.amountPesos)}</p><p><b>Document result:</b> no links found by direct HGAB-title or selected NEP-counterpart route. <b>DEO–LEG crosswalk:</b> ${x.deoLegCrosswalk.length?x.deoLegCrosswalk.map(c=>`${esc(c.leg)} · ${esc(c.status)} · DEO overlap ${fmt(Number(c.deoAreaFraction||0)*100)}%`).join('; '):'No spatially intersecting LEG row in the current crosswalk.'} This is spatial evidence, not project attribution. <b>NEP pairing:</b> ${esc(x.nepPairStatus)} ${x.nepTitle?`· ${esc(x.nepTitle)}`:''}</p><h3>Review flags</h3>${x.flags.length?x.flags.map(f=>`<p><b>${esc(f.label)}</b> · ${esc(f.evidence)}</p>`).join(''):'No line-item review-queue flags joined by HGAB ID.'}<h3>Repeat candidates</h3>${x.historicalMatches.map(m=>`<p>FY${esc(m.gaaYear)} · ${esc(m.gaaTitle)} · ${peso(m.gaaAmountPesos)} · ${esc(m.chainageStatus||'title candidate')}</p>`).join('')||'<p>No historical GAA candidate joined.</p>'}${x.withinStageRepeatPairs.map(p=>`<p>${esc(p.kind)} · ${esc(p.left?.projectName||p.left?.title||'')} ↔ ${esc(p.right?.projectName||p.right?.title||'')} · title similarity ${fmt((p.titleSimilarity||0)*100)}%</p>`).join('')}${x.evidenceCautions?.length?`<h3>Cautions</h3><ul>${x.evidenceCautions.map(c=>`<li>${esc(c)}</li>`).join('')}</ul>`:''}`}document.getElementById('prev').onclick=()=>{pg--;draw()};document.getElementById('next').onclick=()=>{pg++;draw()};[q,flag,program,region,crosswalk,sort].forEach(x=>x.oninput=x.onchange=()=>{pg=0;draw()});document.getElementById('source-note');draw();}).catch(e=>{document.querySelector('main').insertAdjacentHTML('afterbegin',`<div class="warning red">${e.message}</div>`)});</script></body></html>'''
    html=html.replace('__SNAPSHOT__',indepth['hgabCoverage'].get('snapshotRetrievedAtUtc') or 'not stated')
    html=apply_report_chrome(html,'undocumented-hgab.html')
    for p in (OUT/'undocumented-hgab-data.json',STATIC/'undocumented-hgab-data.json'): p.write_text(payload)
    for p in (OUT/'undocumented-hgab.html',STATIC/'undocumented-hgab.html'): p.write_text(html)
    print(json.dumps(data['summary'],indent=2))
if __name__=='__main__':main()
